content.query:
let runs = dependencies
    | where timestamp {TimeRange}
    | where name == "Tv.Subscriptions.ProcessFeed"
    | project RunStart = timestamp, RunOperation = operation_Id, RunSpan = id, Duration = duration, Succeeded = success;
let manual = requests
    | where timestamp {TimeRange}
    | where name == "process tv-feed-notification-process-trigger"
    | distinct RunOperation = operation_Id
    | extend Manual = true;
let users = traces
    | where timestamp {TimeRange}
    | where isnotempty(customDimensions["notification.user_count"])
    | summarize UsersToNotify = max(toint(customDimensions["notification.user_count"])),
        Catalogued = max(toint(customDimensions["nyaa.catalogued_count"])) by RunSpan = operation_ParentId;
let gaps = traces
    | where timestamp {TimeRange}
    | where isnotempty(customDimensions["nyaa.backfill_count"])
    | summarize BackfillsQueued = max(toint(customDimensions["nyaa.backfill_count"])) by RunSpan = operation_ParentId;
let sent = dependencies
    | where timestamp {TimeRange}
    | where name == "send tv-feed-notification"
    | summarize Sent = count(), SendFailures = countif(success == false) by RunOperation = operation_Id;
let hops = requests
    | where timestamp {TimeRange}
    | where name == "process tv-feed-notification"
    | mv-expand link = todynamic(tostring(customDimensions["_MS.links"]))
    | project HopOperation = operation_Id, RunOperation = tostring(link.operation_Id);
let outcomes = hops
    | join kind=inner (dependencies
        | where timestamp {TimeRange}
        | where name == "Tv.Subscriptions.NotifyUser"
        | project HopOperation = operation_Id, NotifySucceeded = success) on HopOperation
    | summarize Processed = count(), Failed = countif(NotifySucceeded == false) by RunOperation;
runs
| join kind=leftouter manual on RunOperation
| join kind=leftouter users on RunSpan
| join kind=leftouter gaps on RunSpan
| join kind=leftouter sent on RunOperation
| join kind=leftouter outcomes on RunOperation
| project RunStart, Trigger = iff(Manual == true, "manual", "timer"), Duration, Succeeded, Catalogued,
    BackfillsQueued = coalesce(BackfillsQueued, 0), UsersToNotify,
    Sent = coalesce(Sent, 0), SendFailures = coalesce(SendFailures, 0),
    Processed = coalesce(Processed, 0), Failed = coalesce(Failed, 0), RunOperation
| order by RunStart desc

let run = "{NotificationRun}";
let hops = requests
    | where timestamp {TimeRange}
    | where name == "process tv-feed-notification"
    | mv-expand link = todynamic(tostring(customDimensions["_MS.links"]))
    | where tostring(link.operation_Id) == run
    | distinct operation_Id;
let users = traces
    | where timestamp {TimeRange}
    | where operation_Id in (hops) and isnotempty(customDimensions["user.id"])
    | summarize UserId = take_any(tostring(customDimensions["user.id"])),
        Notifications = max(toint(customDimensions["notification.count"])) by SpanId = operation_ParentId;
dependencies
| where timestamp {TimeRange}
| where name == "Tv.Subscriptions.NotifyUser" and operation_Id in (hops)
| join kind=leftouter users on $left.id == $right.SpanId
| project timestamp, UserId, Notifications, Duration = duration, Succeeded = success,
    ErrorType = tostring(customDimensions["error.type"]), HopOperation = operation_Id
| order by timestamp asc

let runs = dependencies
    | where timestamp {TimeRange}
    | where type == "InProc" and name in ("Tv.FeedManager.AutomatedBinding", "Tv.FeedManager.SettleFeeds")
    | project RunStart = timestamp, Job = substring(name, 15), RunSpan = id, RunOperation = operation_Id, Duration = duration,
        Succeeded = success, ErrorType = tostring(customDimensions["error.type"]);
let manual = requests
    | where timestamp {TimeRange}
    | where name in ("process run-automated-binding", "process run-feed-settlement")
    | distinct RunOperation = operation_Id
    | extend Manual = true;
let outcomes = traces
    | where timestamp {TimeRange}
    | where isnotempty(customDimensions["nyaa.queued_count"]) or isnotempty(customDimensions["nyaa.stamped_count"])
    | summarize Outcome = take_any(replace_regex(message, @"^\((Scheduled|Manual)\) |\. Next run: .*$", "")) by RunSpan = operation_ParentId;
runs
| join kind=leftouter manual on RunOperation
| join kind=leftouter outcomes on RunSpan
| project RunStart, Job, Trigger = iff(Manual == true, "manual", "timer"), Duration, Succeeded, ErrorType, Outcome, RunOperation
| order by RunStart desc

let run = "{LibraryRun}";
let hops = requests
    | where timestamp {TimeRange}
    | where name startswith "process "
    | mv-expand link = todynamic(tostring(customDimensions["_MS.links"]))
    | where tostring(link.operation_Id) == run
    | project HopOperation = operation_Id, Queue = substring(name, 8);
let failures = dependencies
    | where timestamp {TimeRange}
    | where type == "InProc" and success == false
    | summarize ErrorTypes = strcat_array(make_set(tostring(customDimensions["error.type"])), ", ") by HopOperation = operation_Id;
hops
| join kind=leftouter failures on HopOperation
| summarize Messages = count(), Failed = countif(isnotempty(ErrorTypes)), ErrorTypes = make_set_if(ErrorTypes, isnotempty(ErrorTypes)) by Queue
| order by Messages desc

let spans = dependencies
    | where timestamp {TimeRange}
    | where name == "Seasons.Update"
    | project id;
traces
| where timestamp {TimeRange}
| where operation_ParentId in (spans) and isnotempty(customDimensions["series.season"])
| project timestamp, Season = tostring(customDimensions["series.season"]), Outcome = message, Operation = operation_Id
| order by timestamp desc

let imports = dependencies
    | where timestamp {TimeRange}
    | where name == "Tv.Library.Import"
    | distinct operation_Id;
traces
| where timestamp {TimeRange}
| where operation_Id in (imports) and severityLevel == 2 and message has "without an image"
| project timestamp, Series = tostring(customDimensions["series.title"]), Reason = tostring(customDimensions["domain_error.message"]),
    Operation = operation_Id
| order by timestamp desc
